import json,subprocess,re
repo='/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill'
msgs=json.load(open('/tmp/rosswork/msgs.json'))
from collections import defaultdict
bset=defaultdict(set)
for m in msgs: bset[m['ep']].add(m['sha'])
files=subprocess.run(['git','-C',repo,'ls-tree','-r','--name-only','origin/main'],capture_output=True,text=True).stdout.split()
tot_ok=True
for f in files:
    if not re.match(r'^S\d+/E\d+\.md$',f): continue
    body=subprocess.run(['git','-C',repo,'show','origin/main:'+f],capture_output=True,text=True).stdout
    srcs=re.findall(r'^Source: friend/(\w+) @ ([0-9a-f]{40})\s*$',body,re.M)
    lines=[l for l in body.split('\n') if l.startswith('Source: ')]
    have={s for _,s in srcs}
    want=bset.get(f,set())
    status='OK'
    if want-have: status='MISSING %d'%len(want-have)
    if have-want: status+=' EXTRA %d'%len(have-want)
    if len(srcs)!=len(lines): status+=' LINES %d vs %d'%(len(srcs),len(lines))
    if len(srcs)!=len(have): status+=' DUP %d'%(len(srcs)-len(have))
    if status!='OK':
        tot_ok=False
        print(f,status)
        for x in sorted(want-have): print('   missing',x)
        for x in sorted(have-want): print('   extra',x)
print('all consistent' if tot_ok else 'issues above')
EOF

